import { registerSessionRoutes } from './session-routes';

export function registerRoutes(app, db) {
  app.get('/getWidgets', async (_req, res) => {
    res.json(await db.widgets.all());
  });

  app.post('/widgets', async (req, res) => {
    const widget = await db.widgets.create(req.body);
    res.status(200).json(widget);
  });

  app.get('/widgets/:id', async (req, res) => {
    const item = await db.widgets.get(req.params.id);
    if (!item) return res.status(404).json({ message: 'missing' });
    res.json(item);
  });

  app.get('/widgets/:widgetId/status', async (req, res) => {
    const row = await db.widgets.status(req.params.widgetId);
    res.json({ state: row.state, retryCount: row.attempts.length });
  });

  app.get('/widgets/:widgetId/owner', async (req, res) => {
    const owner = await db.widgets.owner(req.params.widgetId);
    const body = { id: owner.id };
    if (owner.email !== null && owner.email !== undefined) body.email = owner.email;
    res.json(body);
  });

  app.get('/users/:userId', async (req, res) => {
    res.json(await db.users.get(req.params.userId));
  });

  registerSessionRoutes(app, db);
}

export function registerSessionRoutes(app, db) {
  app.get('/users/:userId/sessions', async (req, res) => {
    res.json(await db.sessions.forUser(req.params.userId));
  });
}

// Precision/recall oracle for the API contract review.
//
// Run by the harness with the reviewed workspace as cwd. It grades the two
// halves of a real reconciliation separately, because recall alone is passed
// by a report that flags every operation it could not instantly match:
//
//   RECALL    - each of the three REAL drifts between openapi.yaml and the
//               route inventory is reported, matched by path AND class.
//   PRECISION - none of the three SAFE operations is CLAIMED to drift. Each
//               is a deliberate look-alike of a real drift, and each is
//               documented as correct in docs/api-contract.md.
//
// Classes are matched by their ordinary names - documented but not
// implemented, implemented but not documented, response schema mismatch - and
// never by wording this fixture invented, so the bar is "a real contract
// reconciliation" rather than this scenario's vocabulary.
//
// Three rules keep the precision half off correct work, because a gate that
// punishes a good review is worse than no gate at all:
//
//   1. A record is judged by what it is ABOUT - its path/endpoint field - not
//      by every string it contains. Citing a neighbouring operation as the
//      model for a fix ("add a path item like /widgets/{widgetId}/owner") is
//      normal review prose, not a claim against that neighbour.
//   2. Precision fires only on a reconciliation CLAIM: missing handler,
//      undocumented operation, schema or parameter disagreement. Saying a
//      safe operation has no pagination, no security scheme or no documented
//      404 is TRUE of this fixture and is fair review - those design smells
//      are graded by the api-review.md checks, never punished here. HARD
//      claims name the operation itself and always count; SOFT claims leave
//      the subject implicit ("missing from the spec") and are read as design
//      remarks when they sit in a clause about a design feature.
//   3. A "this one is fine" verdict is a non-claim only when it asserts no
//      drift class. That keeps ordinary remediation wording - "change the
//      type so the schema matches the handler" - from erasing a real finding,
//      and stops a false positive from being excused by appending "no drift".
//
// The recall classes are built from the same families as the precision
// claims, so a record that satisfies recall can never be discarded as a
// verdict, and the two halves cannot drift apart as the vocabulary grows.
import { readFileSync } from 'node:fs';

/**
 * Fail with the message ALONE on stderr.
 *
 * A thrown Error would work, but the harness feeds this script's stderr
 * into the model's repair nudge verbatim, and an uncaught throw pads that
 * nudge with a Node stack trace and a version banner. The actionable
 * sentence is what the next attempt needs; the stack is noise that pushes
 * it out of view on a small model.
 */
function fail(message) {
  console.error(message);
  process.exit(1);
}


const DRIFT = 'tasks/eval/drift.json';

let raw;
try {
  raw = readFileSync(DRIFT, 'utf8');
} catch {
  fail(DRIFT + ' does not exist - the machine-readable drift list is required');
}

let records;
try {
  records = JSON.parse(raw.replace(/^\uFEFF/, ''));
} catch (err) {
  fail(DRIFT + ' is not valid JSON: ' + err.message);
}
if (!Array.isArray(records)) {
  const arrays =
    records && typeof records === 'object' ? Object.values(records).filter(Array.isArray) : [];
  if (arrays.length === 0) fail(DRIFT + ' must be an array of drift records');
  records = arrays.flat();
}

function strings(value, out) {
  if (typeof value === 'string') out.push(value);
  else if (Array.isArray(value)) for (const entry of value) strings(entry, out);
  else if (value && typeof value === 'object')
    for (const entry of Object.values(value)) strings(entry, out);
  return out;
}

const union = (...parts) => new RegExp(parts.map((part) => part.source).join('|'));

// `{widgetId}` and `:widgetId` are the same parameter; the contract and the
// router spell it differently and a review may quote either form.
const normalize = (text) =>
  text
    .toLowerCase()
    .replace(/\{\s*([a-z0-9_]+)\s*\}/g, ':$1')
    // Mark sentence ends with `;` so the clause-scoped spans below cannot
    // borrow words from the next sentence - but leave the dot inside
    // `src/routes.ts` and `row.attempts.length` alone, or every clause would
    // stop at the first filename a review cites as evidence.
    .replace(/\.(?=\s|$)/g, ' ; ');

const textOf = (record) => normalize(strings(record, []).join(' | '));

// What a record is ABOUT. The drift list is one record per operation and the
// record schema requires a `path`, so the identifying fields are the honest
// subject; `issue` and `fix` prose routinely names other operations.
const SUBJECT_KEY = /^(api)?(path|endpoint|operation|operationid|route|url|uri|resource)s?$/;
function subjectOf(record) {
  const parts = [];
  for (const [key, value] of Object.entries(record)) {
    if (SUBJECT_KEY.test(key.toLowerCase().replace(/[^a-z]/g, ''))) strings(value, parts);
  }
  return parts.length > 0 ? normalize(parts.join(' | ')) : null;
}

// ---------------------------------------------------------------------------
// The ordinary vocabulary for "the contract and the code disagree". Prose is
// joined with ` | ` and clause spans never cross `;` or `|`, so one sentence
// cannot borrow words from the next.
// ---------------------------------------------------------------------------

// HARD: the operation itself is named as the thing that is wrong.
const NO_HANDLER = union(
  /no (matching |registered |corresponding )?(route|handler|endpoint)\b/,
  /missing (route|handler|endpoint)\b/,
  /(handler|route|endpoint)[^;|]{0,40}(is |are )?(missing|absent|not found|not registered|does not exist|doesn'?t exist)/,
  /(missing|absent) from (the )?(route|router|code|src|handler)/,
  /not (present|found|registered|defined) in (the )?(route|router|code|src)/,
  /not (registered|implemented|defined|handled) (by|in) (either|any|both)/,
  /neither[^;|]{0,80}(register|implement|defin|handl)/,
  /(none of|not one of)[^;|]{0,60}(route|file|handler)[^;|]{0,40}(register|implement|defin|handl)/,
  /does not appear in (either|any|both|the) ?(of the )?(route|router|code|file)/,
  /(nothing|no code|no file|nowhere)[^;|]{0,30}implement/,
  /(code|implementation|router?|server|service|app)[^;|]{0,30}(does not|doesn'?t) implement/,
  /(could not|couldn'?t|cannot|can'?t|unable to) (find|locate|see)[^;|]{0,40}(handler|route|endpoint|implementation)/,
  /lacks (a |an )?(handler|route|implementation)\b/,
  /ghost (route|endpoint|operation|path)/,
  /orphan(ed)? (spec|contract|path|operation|entry)/,
  /spec[- ]only/,
  /dead (spec|contract) entry/,
);

const NO_PATH_ITEM = union(
  /undocumented (operation|endpoint|route|path|handler)/,
  /(operation|endpoint|route|path|handler)[^;|]{0,40}(is |are )?(not documented|undocumented)/,
  /no path item/,
  /no (matching |corresponding )?(spec|contract|openapi(\.yaml)?) (entry|path item)/,
  /shadow (route|endpoint)/,
  /(spec|contract|openapi(\.yaml)?)[^;|]{0,50}(does not|doesn'?t|fails to) (document|include|list|cover|mention)[^;|]{0,15}\b(it|this|that|the (operation|endpoint|route|path))\b/,
  /(spec|contract|openapi(\.yaml)?)[^;|]{0,40}(omits|lacks|has no|says nothing about)[^;|]{0,15}\b(it|this|that|entry|path item|the (operation|endpoint|route|path))\b/,
);

const SCHEMA_DISAGREEMENT = union(
  /schema mismatch|response mismatch|type mismatch/,
  /type (conflict|disagreement|drift)/,
  /wrong type|incorrect type/,
  /(does not|doesn'?t) match the (schema|contract|spec|declared)/,
  /(violates|contradicts) the (schema|contract|spec)/,
  /(declar\w+|documented)[^;|]{0,40}\b(string|number|integer|boolean|array|object)\b[^;|]{0,80}(returns|sends|responds|actually|but)/,
  /required (field|property|member)[^;|]{0,40}(missing|omitted|absent|not returned)/,
  /(omits|drops|does not return|doesn'?t return|never returns)[^;|]{0,40}(email|required)/,
);

const PARAM_DISAGREEMENT = union(
  /param\w*[^;|]{0,60}(mismatch|mismatched|differ|do(es)? not match|doesn'?t match|inconsistent|drift)/,
  /(templat|naming)\w*[^;|]{0,60}(mismatch|differ|drift|inconsistent)/,
);

// SOFT: the subject is implicit, so these are also how a reviewer says a
// design feature is absent. They count against precision only outside a
// clause about such a feature.
const NOT_IMPLEMENTED_LOOSE = union(
  /not implemented|no implementation|missing implementation|unimplemented|never implemented/,
  /implemented nowhere/,
  /(missing|absent) from (the )?implementation/,
);

const NOT_DOCUMENTED_LOOSE = union(
  /not documented|undocumented|documented nowhere/,
  /(missing|absent) from (the )?(spec|contract|openapi)/,
  /not in (the )?(spec|contract|openapi)/,
);

const HARD_CLAIM = union(NO_HANDLER, NO_PATH_ITEM, SCHEMA_DISAGREEMENT, PARAM_DISAGREEMENT);
const SOFT_CLAIM = union(NOT_IMPLEMENTED_LOOSE, NOT_DOCUMENTED_LOOSE);

// A clause whose subject is a design feature rather than the operation. Every
// one of these is genuinely absent from this fixture, so a reviewer naming it
// is right and must not be charged with inventing drift.
const DESIGN_CLAUSE =
  /[^;|]*\b(pagination|paginat\w+|cursor|offset|page size|security|securityschemes?|scopes?|auth\w*|oauth|401|403|404|4xx|5xx|error responses?|status codes?|examples?|descriptions?|summar\w+|naming|verb in (the )?path|rate[- ]limit\w*|versioning|idempoten\w+|cach\w+|etag|headers?|content[- ]type)\b[^;|]*/g;

const claimsDrift = (text) =>
  HARD_CLAIM.test(text) || SOFT_CLAIM.test(text.replace(DESIGN_CLAUSE, ' '));

// Recall is deliberately more generous than precision: extra tolerance here
// only risks passing a sloppy review, while a miss fails a correct one.
const TYPE_EVIDENCE =
  /(?<!\bno )mismatch|(?<!\bno )not match|doesn'?t match|typed as|should be (a |an )?(number|integer)|declar\w*[\s\S]{0,60}\b(string|number|integer)\b|\bstring\b[\s\S]{0,120}\b(number|integer)\b|\b(number|integer)\b[\s\S]{0,120}\bstring\b/;

const REAL = [
  {
    label:
      'GET /widgets/{widgetId}/history is documented in openapi.yaml but no handler implements it',
    path: /\/widgets\/:[a-z0-9_]+\/history/,
    klass: union(
      NO_HANDLER,
      NOT_IMPLEMENTED_LOOSE,
      /documented but/,
      /only (exists )?in the (spec|contract|openapi)/,
    ),
  },
  {
    label:
      'GET /widgets/{widgetId}/status returns retryCount as a number while the contract declares it a string',
    path: /\/widgets\/:[a-z0-9_]+\/status/,
    klass: union(SCHEMA_DISAGREEMENT, TYPE_EVIDENCE),
  },
  {
    label: 'GET /widgets/:id is implemented in src/routes.ts but absent from openapi.yaml',
    path: /\/widgets\/:[a-z0-9_]+(?![a-z0-9_/])/,
    klass: union(
      NO_PATH_ITEM,
      NOT_DOCUMENTED_LOOSE,
      /add[^;|]{0,50}\b(path item|operation|entry|endpoint|route|definition|it)\b[^;|]{0,20}\bto\b[^;|]{0,15}(spec|contract|openapi)/,
      /document it/,
    ),
  },
];

// A record that states the operation conforms is a verdict, not a drift
// claim - but only when it asserts no drift class of its own.
const NO_DRIFT_VERDICT =
  /no drift|not a drift|not drift|matches the (spec|contract|implementation|handler|schema)|conforms to the (spec|contract)|correct as written|as designed|verified (safe|correct|ok)|no mismatch|no issue|no violation|not a (real )?(issue|violation|finding)|false positive|(permitted|allowed) by the (spec|contract)/;

const assertsDrift = (text) => claimsDrift(text) || REAL.some((real) => real.klass.test(text));

const entries = records
  .filter((record) => record && typeof record === 'object')
  .map((record) => ({ record, text: textOf(record), subject: subjectOf(record) }));

const claims = entries.filter(
  (entry) => assertsDrift(entry.text) || !NO_DRIFT_VERDICT.test(entry.text),
);

const missing = REAL.filter(
  (real) => !claims.some((entry) => real.path.test(entry.text) && real.klass.test(entry.text)),
);
if (missing.length > 0) {
  fail(
    'RECALL FAILURE - openapi.yaml and the route inventory disagree in three places and these ' +
      'were not reported: ' +
      missing.map((real) => real.label).join('; ') +
      '. Reported paths: ' +
      (entries
        .map((entry) => String(entry.record.path ?? entry.record.operation ?? '?'))
        .join(', ') || '(nothing)'),
  );
}

const SAFE = [
  {
    label: 'GET /users/{userId}',
    path: /\/users\/:[a-z0-9_]+(?![a-z0-9_/])/,
    why: 'it is documented AND implemented in src/routes.ts - `{userId}` in the contract and `:userId` in the router are the same path parameter',
  },
  {
    label: 'GET /users/{userId}/sessions',
    path: /\/users\/:[a-z0-9_]+\/sessions/,
    why: 'its handler is registered in src/session-routes.ts, which src/routes.ts imports and calls - reading only one route file is what makes it look missing',
  },
  {
    label: 'GET /widgets/{widgetId}/owner',
    path: /\/widgets\/:[a-z0-9_]+\/owner/,
    why: 'the contract marks `email` nullable and leaves it out of `required`, so a handler that omits it when the owner has no address is permitted',
  },
];

const falsePositives = [];
for (const safe of SAFE) {
  for (const entry of claims) {
    // Judge the record by its subject, so a fix that cites this operation as
    // the model for another one is not counted against the review.
    if (!safe.path.test(entry.subject ?? entry.text)) continue;
    // And only when it actually claims a contract/implementation
    // disagreement - a design remark about a safe operation is fair review.
    if (!claimsDrift(entry.text)) continue;
    falsePositives.push(
      safe.label +
        ' reported as "' +
        String(entry.record.issue ?? entry.record.kind ?? entry.record.type ?? 'drift') +
        '" - ' +
        safe.why,
    );
  }
}
if (falsePositives.length > 0) {
  fail(
    'PRECISION FAILURE - these operations agree with the contract and must not be listed as ' +
      'drift: ' +
      falsePositives.join('; ') +
      '. A reconciliation that invents drift is not usable; re-read docs/api-contract.md and ' +
      'both route files before deciding an operation is missing.',
  );
}

console.log(
  'API contract precision/recall oracle passed: all 3 real drifts reported, 0 false drifts on ' +
    'the 3 safe operations.',
);
